const raw = $input.first().json;
const body = raw.body || raw;
const pick = (a, b, c) => String(a || b || c || '').trim();
const name = pick(body.patient_name, body.name, body.from_name);
const phone = pick(body.patient_phone, body.phone, body.from);
const email = pick(body.patient_email, body.email, '');
const text = pick(body.message_text, body.message, body.text);
const channel = pick(body.channel, 'whatsapp', 'whatsapp');
const issues = [];
if (!text) { issues.push('Empty patient message'); }
if (!phone) { issues.push('No patient phone captured'); }
if (!name) { issues.push('No patient name captured'); }
if (!email) { issues.push('No patient email captured, reply could not be delivered by email'); }
return [{ json: { patient_name: name || 'Unknown Patient', patient_phone: phone, patient_email: email, message_text: text, channel: channel, intake_issues: issues, intake_issue_count: issues.length } }];

const cfg = $('Config').first().json;
const intake = $('Normalise Intake').first().json;
const kbRows = $input.all().map(i => i.json).filter(r => r && (r.question || r.Question));
let kb = '';
kbRows.forEach(r => { kb += String(r.question || r.Question) + ' :: ' + String(r.answer || r.Answer || '') + '\n'; });
if (!kb) { kb = 'Clinic timings 10am to 7pm Monday to Saturday. Walk ins allowed but appointment preferred.'; }
const roster = String(cfg.doctor_roster || '');
const specs = [];
roster.split(';').forEach(pair => { const bits = pair.split('|'); if (bits.length === 2) { specs.push(bits[1].trim()); } });
const phone = String(intake.patient_phone || '').replace(/[^0-9]/g, '').slice(-10);
const hist = $('Read Patient History').all().map(i => i.json).filter(r => r && (r.record_id || r.patient_phone));
const mine = hist.filter(r => String(r.patient_phone || '').replace(/[^0-9]/g, '').slice(-10) === phone && phone.length === 10);
let histText = 'No previous visit on record. Treat as a new patient.';
if (mine.length) {
  histText = '';
  mine.forEach(r => { histText += String(r.appointment_slot || r.received_at || '') + ' | ' + String(r.specialty || '') + ' | ' + String(r.symptoms || '') + ' | seen by ' + String(r.doctor || '') + '\n'; });
}
return [{ json: { kb_text: kb, history_text: histText, visit_count: mine.length, is_returning: mine.length > 0, specialty_list: specs.join(', '), patient_name: intake.patient_name, message_text: intake.message_text } }];

const textOf = (resp) => { const c = resp && resp.candidates && resp.candidates[0]; const parts = (c && c.content && c.content.parts) || []; return parts.filter(p => typeof p.text === 'string' && !p.thought).map(p => p.text).join(''); };
const parseJson = (raw) => { let t = String(raw || '').trim(); const s = t.indexOf('{'); const e = t.lastIndexOf('}'); if (s !== -1 && e !== -1) t = t.slice(s, e + 1); try { return JSON.parse(t); } catch (err) { return null; } };
const cfg = $('Config').first().json;
const intake = $('Normalise Intake').first().json;
const ctx = $('Assemble Context').first().json;
const t = parseJson(textOf($input.first().json)) || {};
const aiOk = !!t.urgency;
const issues = Array.isArray(intake.intake_issues) ? intake.intake_issues.slice(0) : [];
if (!aiOk) { issues.push('Triage AI did not return a valid result, defaulted to urgent for safety'); }
const urgency = String(t.urgency || (aiOk ? 'routine' : 'urgent')).toLowerCase();
const intent = String(t.intent || 'new_appointment');
const redFlags = Array.isArray(t.red_flags) ? t.red_flags : [];
const keyQ = Array.isArray(t.key_questions) ? t.key_questions : [];
let wantedSpec = String(t.specialty || 'General Medicine').trim();
if (wantedSpec.indexOf('|') !== -1) { const wb = wantedSpec.split('|'); wantedSpec = wb[wb.length - 1].trim(); }
const roster = String(cfg.doctor_roster || '');
const docs = [];
roster.split(';').forEach(pair => { const bits = pair.split('|'); if (bits.length === 2) { docs.push({ name: bits[0].trim(), spec: bits[1].trim() }); } });
const ws = wantedSpec.toLowerCase();
let match = docs.find(d => d.spec.toLowerCase() === ws);
if (!match) { match = docs.find(d => ws.indexOf(d.spec.toLowerCase()) !== -1); }
if (!match) { match = docs.find(d => d.spec.toLowerCase().indexOf(ws) !== -1 && ws.length > 3); }
if (!match) { match = docs.find(d => ws.indexOf(d.name.toLowerCase()) !== -1); }
if (!match) { match = docs.find(d => d.spec.toLowerCase().indexOf('general') !== -1); }
if (!match && docs.length) { match = docs[0]; }
if (match && match.spec.toLowerCase() !== ws && ws.length > 2) { issues.push('Triage asked for ' + wantedSpec + ' which is not on the roster, routed to ' + match.spec); }
const doctor = match ? match.name : 'Duty Doctor';
const specialty = match ? match.spec : 'General Medicine';
const openH = Number(cfg.open_hour) || 10;
const closeH = Number(cfg.close_hour) || 19;
const slotMin = Number(cfg.slot_minutes) || 20;
const TZ = Number(cfg.tz_offset_minutes) || 330;
const pad = (n) => String(n).padStart(2, '0');
const fmtDate = (d) => d.getUTCFullYear() + '-' + pad(d.getUTCMonth() + 1) + '-' + pad(d.getUTCDate());
const fmtSlot = (d) => fmtDate(d) + ' ' + pad(d.getUTCHours()) + ':' + pad(d.getUTCMinutes());
const now = new Date(Date.now() + TZ * 60000);
const hist = $('Read Patient History').all().map(i => i.json).filter(r => r && (r.record_id || r.patient_phone));
let slotText = '';
let apptDate = '';
if (urgency === 'emergency') {
  slotText = 'IMMEDIATE - come to the clinic now or call ' + String(cfg.clinic_phone || '');
  apptDate = fmtDate(now);
} else {
  let target = new Date(now.getTime());
  if (urgency === 'urgent') {
    target = new Date(now.getTime() + 2 * 3600000);
    if (target.getUTCHours() >= closeH) { target.setUTCDate(target.getUTCDate() + 1); target.setUTCHours(openH, 0, 0, 0); }
    else if (target.getUTCHours() < openH) { target.setUTCHours(openH, 0, 0, 0); }
    else { target.setUTCMinutes(0, 0, 0); }
  } else {
    target = new Date(now.getTime() + 86400000);
    target.setUTCHours(openH, 0, 0, 0);
  }
  const dStr = fmtDate(target);
  const sameDay = hist.filter(r => String(r.appointment_slot || '').indexOf(dStr) === 0);
  target = new Date(target.getTime() + sameDay.length * slotMin * 60000);
  if (target.getUTCHours() >= closeH) { target.setUTCDate(target.getUTCDate() + 1); target.setUTCHours(openH, 0, 0, 0); }
  slotText = fmtSlot(target);
  apptDate = fmtDate(target);
}
const stamp = now.getUTCFullYear() + pad(now.getUTCMonth() + 1) + pad(now.getUTCDate()) + pad(now.getUTCHours()) + pad(now.getUTCMinutes());
const phoneKey = String(intake.patient_phone || '').replace(/[^0-9]/g, '').slice(-10);
const dedupeMin = Number(cfg.dedupe_minutes) || 30;
const nowMs = now.getTime();
let isDuplicate = false;
hist.forEach(r => { const rp = String(r.patient_phone || '').replace(/[^0-9]/g, '').slice(-10); if (rp && rp === phoneKey) { const ts = Date.parse(String(r.received_at || '').trim().replace(' ', 'T') + 'Z'); if (!isNaN(ts) && (nowMs - ts) < dedupeMin * 60000 && (nowMs - ts) > -60000) { isDuplicate = true; } } });
let flagText = 'none';
if (redFlags.length) { flagText = redFlags.join('; '); }
let qText = '';
keyQ.forEach(q => { qText += '- ' + String(q) + '\n'; });
return [{ json: {
  record_id: 'PR' + stamp,
  appointment_id: 'AP' + stamp,
  received_at: fmtSlot(now),
  channel: intake.channel,
  patient_name: intake.patient_name,
  patient_phone: intake.patient_phone,
  patient_email: intake.patient_email,
  message_text: intake.message_text,
  intent: intent,
  urgency: urgency,
  is_emergency: urgency === 'emergency',
  red_flags: redFlags,
  red_flags_text: flagText,
  symptoms: String(t.symptoms || 'Not clearly stated'),
  duration: String(t.duration || 'unknown'),
  age_hint: String(t.age_hint || 'unknown'),
  language: String(t.language || 'english'),
  summary: String(t.summary || 'Patient enquiry received'),
  kb_answer: String(t.kb_answer || ''),
  key_questions: keyQ,
  key_questions_text: qText || '- Confirm the exact onset and duration\n- Ask about any existing medication\n- Ask about known allergies\n',
  specialty: specialty,
  doctor: doctor,
  appointment_slot: slotText,
  appointment_date: apptDate,
  is_returning: !!ctx.is_returning,
  visit_count: Number(ctx.visit_count) || 0,
  history_text: ctx.history_text,
  clinic_name: cfg.clinic_name,
  clinic_phone: cfg.clinic_phone,
  clinic_address: cfg.clinic_address,
  doctor_email: cfg.doctor_email,
  ai_ok: aiOk,
  is_duplicate: isDuplicate,
  data_issues: issues,
  data_issue_count: issues.length,
  status: urgency === 'emergency' ? 'escalated' : 'booked'
} }];

const textOf = (resp) => { const c = resp && resp.candidates && resp.candidates[0]; const parts = (c && c.content && c.content.parts) || []; return parts.filter(p => typeof p.text === 'string' && !p.thought).map(p => p.text).join(''); };
const parseJson = (raw) => { let t = String(raw || '').trim(); const s = t.indexOf('{'); const e = t.lastIndexOf('}'); if (s !== -1 && e !== -1) t = t.slice(s, e + 1); try { return JSON.parse(t); } catch (err) { return null; } };
const esc = (s) => String(s == null ? '' : s).replace(/&/g, '&amp;').replace(/</g, '&lt;').replace(/>/g, '&gt;');
const d = $('Slot and Route Engine').first().json;
const r = parseJson(textOf($input.first().json)) || {};
const replyOk = !!r.greeting_line;
const greeting = r.greeting_line || ('Namaste ' + d.patient_name + ',');
const bodyLines = Array.isArray(r.body_lines) && r.body_lines.length ? r.body_lines : ['We have received your message and our team will contact you shortly.'];
const prepLines = Array.isArray(r.prep_lines) ? r.prep_lines : [];
const closing = r.closing_line || 'Thank you.';
const SLATE = '#0F2A3D', TEAL = '#0E7C7B', CREAM = '#F4F5F0', WHITE = '#FFFFFF', INK = '#1A1A1A', GREY = '#666666', RED = '#C0392B', AMBER = '#E67E22';
const isEmg = d.urgency === 'emergency';
const accent = isEmg ? RED : (d.urgency === 'urgent' ? AMBER : TEAL);
let bodyHtml = '';
bodyLines.forEach(l => { bodyHtml += '<div style="font-size:15px;color:' + INK + ';line-height:1.6;margin-bottom:9px;">' + esc(l) + '</div>'; });
let prepHtml = '';
prepLines.forEach(l => { prepHtml += '<li style="margin-bottom:6px;">' + esc(l) + '</li>'; });
let plain = greeting + '\n\n';
bodyLines.forEach(l => { plain += l + '\n'; });
if (prepLines.length) { plain += '\nPlease bring:\n'; prepLines.forEach(l => { plain += '- ' + l + '\n'; }); }
plain += '\n' + closing;
const banner = isEmg ? ('<tr><td style="background:' + RED + ';padding:12px 26px;"><div style="color:#FFFFFF;font-size:13px;font-weight:bold;letter-spacing:1px;">URGENT - PLEASE READ IMMEDIATELY</div></td></tr>') : '';
const html = '' +
'<div style="background:' + CREAM + ';padding:22px;font-family:Calibri,Arial,sans-serif;">' +
'<table width="100%" cellpadding="0" cellspacing="0" style="max-width:600px;margin:0 auto;background:' + WHITE + ';border-radius:10px;overflow:hidden;">' +
'<tr><td style="background:' + SLATE + ';padding:22px 26px;">' +
'<div style="color:#7FD1CE;font-size:11px;font-weight:bold;letter-spacing:3px;">APPOINTMENT UPDATE</div>' +
'<div style="color:' + WHITE + ';font-family:Georgia,serif;font-size:22px;font-weight:bold;margin-top:6px;">' + esc(d.clinic_name) + '</div>' +
'</td></tr>' + banner +
'<tr><td style="padding:22px 26px 6px 26px;"><div style="font-size:16px;font-weight:bold;color:' + INK + ';margin-bottom:12px;">' + esc(greeting) + '</div>' + bodyHtml + '</td></tr>' +
'<tr><td style="padding:8px 26px;"><table width="100%" cellpadding="0" cellspacing="0" style="border:1px solid #E4E4DC;border-radius:8px;border-left:4px solid ' + accent + ';">' +
'<tr><td style="padding:12px 14px;font-size:12px;color:' + GREY + ';">Doctor</td><td align="right" style="padding:12px 14px;font-size:14px;font-weight:bold;color:' + SLATE + ';">' + esc(d.doctor) + '</td></tr>' +
'<tr><td style="padding:12px 14px;font-size:12px;color:' + GREY + ';border-top:1px solid #E4E4DC;">Department</td><td align="right" style="padding:12px 14px;font-size:14px;color:' + SLATE + ';border-top:1px solid #E4E4DC;">' + esc(d.specialty) + '</td></tr>' +
'<tr><td style="padding:12px 14px;font-size:12px;color:' + GREY + ';border-top:1px solid #E4E4DC;">Appointment</td><td align="right" style="padding:12px 14px;font-size:14px;font-weight:bold;color:' + accent + ';border-top:1px solid #E4E4DC;">' + esc(d.appointment_slot) + '</td></tr>' +
'<tr><td style="padding:12px 14px;font-size:12px;color:' + GREY + ';border-top:1px solid #E4E4DC;">Reference</td><td align="right" style="padding:12px 14px;font-size:13px;color:' + GREY + ';border-top:1px solid #E4E4DC;">' + esc(d.appointment_id) + '</td></tr>' +
'</table></td></tr>' +
(prepHtml ? ('<tr><td style="padding:16px 26px 4px 26px;"><div style="font-size:13px;font-weight:bold;color:' + SLATE + ';margin-bottom:6px;">Please bring with you</div><ul style="font-size:14px;color:' + INK + ';line-height:1.5;margin:0;padding-left:20px;">' + prepHtml + '</ul></td></tr>') : '') +
'<tr><td style="padding:16px 26px 20px 26px;"><div style="font-size:14px;color:' + INK + ';">' + esc(closing) + '</div>' +
'<div style="font-size:13px;color:' + GREY + ';margin-top:12px;">' + esc(d.clinic_address) + '<br>Call us: ' + esc(d.clinic_phone) + '</div></td></tr>' +
'<tr><td style="background:' + CREAM + ';padding:12px 26px;"><div style="font-size:11px;color:' + GREY + ';line-height:1.45;">This message is an appointment confirmation only. It is not medical advice or a diagnosis. In an emergency please call ' + esc(d.clinic_phone) + ' or go to the nearest emergency room.</div></td></tr>' +
'</table></div>';
return [{ json: { patient_reply_html: html, patient_reply_text: plain, reply_ok: replyOk } }];

const textOf = (resp) => { const c = resp && resp.candidates && resp.candidates[0]; const parts = (c && c.content && c.content.parts) || []; return parts.filter(p => typeof p.text === 'string' && !p.thought).map(p => p.text).join(''); };
const parseJson = (raw) => { let t = String(raw || '').trim(); const s = t.indexOf('{'); const e = t.lastIndexOf('}'); if (s !== -1 && e !== -1) t = t.slice(s, e + 1); try { return JSON.parse(t); } catch (err) { return null; } };
const esc = (s) => String(s == null ? '' : s).replace(/&/g, '&amp;').replace(/</g, '&lt;').replace(/>/g, '&gt;');
const d = $('Slot and Route Engine').first().json;
const b = parseJson(textOf($input.first().json)) || {};
const briefOk = !!b.chief_complaint;
const replyOk = !!($('Build Patient Reply').first().json.reply_ok);
const chief = b.chief_complaint || d.symptoms || 'Patient enquiry received';
const histNote = b.history_note || (d.is_returning ? ('Returning patient with ' + d.visit_count + ' previous visit(s) on record.') : 'First recorded visit.');
const obs = Array.isArray(b.observations) ? b.observations : [];
const qs = Array.isArray(b.questions_to_ask) && b.questions_to_ask.length ? b.questions_to_ask : (Array.isArray(d.key_questions) ? d.key_questions : []);
const prep = b.prep_note || 'Keep previous reports and vitals ready.';
const caution = b.caution_note || 'This is an automated intake summary and not a clinical assessment.';
const SLATE = '#0F2A3D', TEAL = '#0E7C7B', CREAM = '#F4F5F0', WHITE = '#FFFFFF', INK = '#1A1A1A', GREY = '#666666', RED = '#C0392B', AMBER = '#E67E22';
const uc = d.urgency === 'emergency' ? RED : (d.urgency === 'urgent' ? AMBER : TEAL);
const ucLabel = String(d.urgency || 'routine').toUpperCase();
const issues = Array.isArray(d.data_issues) ? d.data_issues.slice(0) : [];
if (!briefOk) { issues.push('Brief AI was unavailable, showing captured intake data only'); }
if (!replyOk) { issues.push('Patient reply AI was unavailable, a fallback reply was sent'); }
if (d.is_duplicate) { issues.push('Possible duplicate message from the same number within the dedupe window'); }
let bannerHtml = '';
if (issues.length) { bannerHtml = '<tr><td style="padding:12px 26px 0 26px;"><div style="background:#FBE9E7;border-left:4px solid ' + RED + ';border-radius:6px;padding:11px 13px;font-size:12.5px;color:#7A1F14;"><strong>Heads up.</strong> ' + esc(issues.slice(0, 3).join('; ')) + '</div></td></tr>'; }
let obsHtml = '';
obs.forEach(o => { obsHtml += '<li style="margin-bottom:6px;">' + esc(o) + '</li>'; });
let qHtml = '';
qs.forEach(q => { qHtml += '<li style="margin-bottom:7px;">' + esc(q) + '</li>'; });
const flagsBlock = (d.red_flags_text && d.red_flags_text !== 'none') ? ('<tr><td style="padding:14px 26px 0 26px;"><div style="background:#FBE9E7;border-left:4px solid ' + RED + ';border-radius:6px;padding:13px 15px;"><div style="font-size:11px;font-weight:bold;color:#7A1F14;letter-spacing:1px;">RED FLAGS</div><div style="font-size:14.5px;color:#7A1F14;font-weight:bold;margin-top:5px;">' + esc(d.red_flags_text) + '</div></div></td></tr>') : '';
const html = '' +
'<div style="background:' + CREAM + ';padding:22px;font-family:Calibri,Arial,sans-serif;">' +
'<table width="100%" cellpadding="0" cellspacing="0" style="max-width:640px;margin:0 auto;background:' + WHITE + ';border-radius:10px;overflow:hidden;">' +
'<tr><td style="background:' + SLATE + ';padding:22px 26px;">' +
'<div style="color:#7FD1CE;font-size:11px;font-weight:bold;letter-spacing:3px;">PRE CONSULTATION BRIEF</div>' +
'<div style="color:' + WHITE + ';font-family:Georgia,serif;font-size:25px;font-weight:bold;margin-top:7px;">' + esc(d.patient_name) + '</div>' +
'<div style="color:#9AB2C0;font-size:13px;margin-top:5px;">' + esc(d.patient_phone) + ' &middot; ' + esc(d.age_hint) + ' &middot; via ' + esc(d.channel) + ' &middot; ' + esc(d.received_at) + ' IST</div>' +
'</td></tr>' + bannerHtml +
'<tr><td style="padding:16px 26px 4px 26px;"><table width="100%" cellpadding="0" cellspacing="0"><tr>' +
'<td align="center" style="background:' + uc + ';border-radius:6px;padding:12px 6px;"><div style="color:#FFFFFF;font-size:15px;font-weight:bold;">' + ucLabel + '</div><div style="color:#F0F0F0;font-size:10.5px;">triage</div></td>' +
'<td width="8"></td>' +
'<td align="center" style="background:' + CREAM + ';border-radius:6px;padding:12px 6px;"><div style="color:' + SLATE + ';font-size:14px;font-weight:bold;">' + esc(d.specialty) + '</div><div style="color:' + GREY + ';font-size:10.5px;">department</div></td>' +
'<td width="8"></td>' +
'<td align="center" style="background:' + CREAM + ';border-radius:6px;padding:12px 6px;"><div style="color:' + SLATE + ';font-size:14px;font-weight:bold;">' + esc(d.doctor) + '</div><div style="color:' + GREY + ';font-size:10.5px;">assigned</div></td>' +
'<td width="8"></td>' +
'<td align="center" style="background:' + CREAM + ';border-radius:6px;padding:12px 6px;"><div style="color:' + SLATE + ';font-size:13px;font-weight:bold;">' + esc(d.visit_count) + '</div><div style="color:' + GREY + ';font-size:10.5px;">past visits</div></td>' +
'</tr></table></td></tr>' + flagsBlock +
'<tr><td style="padding:16px 26px 4px 26px;"><div style="font-family:Georgia,serif;font-size:15px;font-weight:bold;color:' + SLATE + ';">Chief complaint</div>' +
'<div style="font-size:15px;color:' + INK + ';line-height:1.55;margin-top:5px;">' + esc(chief) + '</div>' +
'<div style="font-size:13px;color:' + GREY + ';margin-top:7px;">Duration: ' + esc(d.duration) + '</div></td></tr>' +
'<tr><td style="padding:14px 26px 4px 26px;"><div style="font-family:Georgia,serif;font-size:15px;font-weight:bold;color:' + SLATE + ';">History</div>' +
'<div style="font-size:14px;color:' + INK + ';line-height:1.55;margin-top:5px;">' + esc(histNote) + '</div></td></tr>' +
(obsHtml ? ('<tr><td style="padding:14px 26px 4px 26px;"><div style="font-family:Georgia,serif;font-size:15px;font-weight:bold;color:' + SLATE + ';">Reported by the patient</div><ul style="font-size:14px;color:' + INK + ';line-height:1.5;margin:6px 0 0 0;padding-left:20px;">' + obsHtml + '</ul></td></tr>') : '') +
(qHtml ? ('<tr><td style="padding:16px 26px;"><table width="100%" cellpadding="0" cellspacing="0" style="background:' + SLATE + ';border-radius:8px;"><tr><td style="padding:18px 20px;"><div style="color:#7FD1CE;font-family:Georgia,serif;font-size:15px;font-weight:bold;margin-bottom:9px;">Ask the patient</div><ul style="color:#E4ECF0;font-size:14px;line-height:1.5;margin:0;padding-left:20px;">' + qHtml + '</ul></td></tr></table></td></tr>') : '') +
'<tr><td style="padding:0 26px 6px 26px;"><div style="background:' + CREAM + ';border-radius:6px;padding:12px 14px;font-size:13px;color:' + INK + ';"><strong>Front desk:</strong> ' + esc(prep) + '</div></td></tr>' +
'<tr><td style="padding:8px 26px 18px 26px;"><div style="font-size:11.5px;color:' + GREY + ';line-height:1.45;">' + esc(caution) + ' Patient words are reproduced as received. Ref ' + esc(d.record_id) + '.</div></td></tr>' +
'<tr><td style="background:' + SLATE + ';padding:12px 26px;"><div style="color:#9AB2C0;font-size:11px;">' + esc(d.clinic_name) + ' &middot; Patient Journey Agent &middot; Powered by Haus of Intelligence</div></td></tr>' +
'</table></div>';
return [{ json: { doctor_brief_html: html, brief_ok: briefOk, issue_count: issues.length } }];
